from fastapi import FastAPI, HTTPException, Query, Body
from pydantic import BaseModel

from app.core import create_jwt

app = FastAPI(title="FF MAX Guest -> JWT API", version="1.0.0")


class TokenRequest(BaseModel):
    uid: str
    password: str


@app.get("/")
async def root():
    return {"message": "Use POST /api/token (JSON) ya GET /api/token?uid=...&password=..."}


@app.get("/api/token")
async def get_token(uid: str = Query(...), password: str = Query(...)):
    try:
        return await create_jwt(uid, password)
    except ValueError as e:
        raise HTTPException(status_code=401, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))


@app.post("/api/token")
async def post_token(payload: TokenRequest = Body(...)):
    try:
        return await create_jwt(payload.uid, payload.password)
    except ValueError as e:
        raise HTTPException(status_code=401, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))

